16	package io.netty.resolver.dns;
17	
18	import io.netty.channel.EventLoop;
19	
20	import java.util.ArrayList;
21	import java.util.Collections;
22	import java.util.Iterator;
23	import java.util.List;
24	import java.util.Map;
25	import java.util.Map.Entry;
26	import java.util.concurrent.ConcurrentHashMap;
27	import java.util.concurrent.ConcurrentMap;
28	import java.util.concurrent.Delayed;
29	import java.util.concurrent.ScheduledFuture;
30	import java.util.concurrent.TimeUnit;
31	import java.util.concurrent.atomic.AtomicReference;
32	import java.util.concurrent.atomic.AtomicReferenceFieldUpdater;
33	
34	import static java.util.Collections.singletonList;
35	
36	/**
37	 * Abstract cache that automatically removes entries for a hostname once the TTL for an entry is reached.
38	 *
39	 * @param <E>
40	 */
41	abstract class Cache<E> {
42	    private static final AtomicReferenceFieldUpdater<Cache.Entries, ScheduledFuture> FUTURE_UPDATER =
43	            AtomicReferenceFieldUpdater.newUpdater(Cache.Entries.class, ScheduledFuture.class, "expirationFuture");
44	
45	    private static final ScheduledFuture<?> CANCELLED = new ScheduledFuture<Object>() {
46	
47	        @Override
48	        public boolean cancel(boolean mayInterruptIfRunning) {
49	            return false;
50	        }
51	
52	        @Override
53	        public long getDelay(TimeUnit unit) {
54	            // We ignore unit and always return the minimum value to ensure the TTL of the cancelled marker is
55	            // the smallest.
56	            return Long.MIN_VALUE;
57	        }
58	
59	        @Override
60	        public int compareTo(Delayed o) {
61	            throw new UnsupportedOperationException();
62	        }
63	
64	        @Override
65	        public boolean isCancelled() {
66	            return true;
67	        }
68	
69	        @Override
70	        public boolean isDone() {
71	            return true;
72	        }
73	
74	        @Override
75	        public Object get() {
76	            throw new UnsupportedOperationException();
77	        }
78	
79	        @Override
80	        public Object get(long timeout, TimeUnit unit) {
81	            throw new UnsupportedOperationException();
82	        }
83	    };
84	
85	    // Two years are supported by all our EventLoop implementations and so safe to use as maximum.
86	    // See also: https://github.com/netty/netty/commit/b47fb817991b42ec8808c7d26538f3f2464e1fa6
87	    static final int MAX_SUPPORTED_TTL_SECS = (int) TimeUnit.DAYS.toSeconds(365 * 2);
88	
89	    private final ConcurrentMap<String, Entries> resolveCache = new ConcurrentHashMap<>();
90	
91	    /**
92	     * Remove everything from the cache.
93	     */
94	    final void clear() {
95	        while (!resolveCache.isEmpty()) {
96	            for (Iterator<Entry<String, Entries>> i = resolveCache.entrySet().iterator(); i.hasNext();) {
97	                Map.Entry<String, Entries> e = i.next();
98	                i.remove();
99	
100	                e.getValue().clearAndCancel();
101	            }
102	        }
103	    }
104	
105	    /**
106	     * Clear all entries (if anything exists) for the given hostname and return {@code true} if anything was removed.
107	     */
108	    final boolean clear(String hostname) {
109	        Entries entries = resolveCache.remove(hostname);
110	        return entries != null && entries.clearAndCancel();
111	    }
112	
113	    /**
114	     * Returns all caches entries for the given hostname.
115	     */
116	    final List<? extends E> get(String hostname) {
117	        Entries entries = resolveCache.get(hostname);
118	        return entries == null ? null : entries.get();
119	    }
120	
121	    /**
122	     * Cache a value for the given hostname that will automatically expire once the TTL is reached.
123	     */
124	    final void cache(String hostname, E value, int ttl, EventLoop loop) {
125	        for (;;) {
126	            Entries entries = resolveCache.get(hostname);
127	            if (entries == null) {
128	                entries = new Entries(hostname);
129	                Entries oldEntries = resolveCache.putIfAbsent(hostname, entries);
130	                if (oldEntries != null) {
131	                    entries = oldEntries;
132	                }
133	            }
134	            if (entries.add(value, ttl, loop)) {
135	                break;
136	            }
137	            // Entries is in CANCELLED state (evicted by its expiry timer). Help remove it from the
138	            // map immediately so the next iteration gets a fresh Entries rather than spinning on
139	            // the same CANCELLED instance until run() finishes its own remove call.
140	            resolveCache.remove(hostname, entries);
141	        }
142	    }
143	
144	    /**
145	     * Return the number of hostnames for which we have cached something.
146	     */
147	    final int size() {
148	        return resolveCache.size();
149	    }
150	
151	    /**
152	     * Returns {@code true} if this entry should replace all other entries that are already cached for the hostname.
153	     */
154	    protected abstract boolean shouldReplaceAll(E entry);
155	
156	    /**
157	     * Sort the {@link List} for a {@code hostname} before caching these.
158	     */
159	    protected void sortEntries(
160	            @SuppressWarnings("unused") String hostname, @SuppressWarnings("unused") List<E> entries) {
161	        // NOOP.
162	    }
163	
164	    /**
165	     * Returns {@code true} if both entries are equal.
166	     */
167	    protected abstract boolean equals(E entry, E otherEntry);
168	
169	    // Directly extend AtomicReference for intrinsics and also to keep memory overhead low.
170	    private final class Entries extends AtomicReference<List<E>> implements Runnable {
171	
172	        private final String hostname;
173	        // Needs to be package-private to be able to access it via the AtomicReferenceFieldUpdater
174	        volatile ScheduledFuture<?> expirationFuture;
175	
176	        Entries(String hostname) {
177	            super(Collections.<E>emptyList());
178	            this.hostname = hostname;
179	        }
180	
181	        boolean add(E e, int ttl, EventLoop loop) {
182	            if (!shouldReplaceAll(e)) {
183	                for (;;) {
184	                    List<E> entries = get();
185	                    if (!entries.isEmpty()) {
186	                        final E firstEntry = entries.get(0);
187	                        if (shouldReplaceAll(firstEntry)) {
188	                            assert entries.size() == 1;
189	
190	                            if (compareAndSet(entries, singletonList(e))) {
191	                                return scheduleCacheExpirationIfNeeded(ttl, loop);
192	                            } else {
193	                                // Need to try again as CAS failed
194	                                continue;
195	                            }
196	                        }
197	
198	                        // Create a new List for COW semantics
199	                        List<E> newEntries = new ArrayList<E>(entries.size() + 1);
200	                        int i = 0;
201	                        E replacedEntry = null;
202	                        do {
203	                            E entry = entries.get(i);
204	                            // Only add old entry if the address is not the same as the one we try to add as well.
205	                            // In this case we will skip it and just add the new entry as this may have
206	                            // more up-to-date data and cancel the old after we were able to update the cache.
207	                            if (!Cache.this.equals(e, entry)) {
208	                                newEntries.add(entry);
209	                            } else {
210	                                replacedEntry = entry;
211	                                newEntries.add(e);
212	
213	                                ++i;
214	                                for (; i < entries.size(); ++i) {
215	                                    newEntries.add(entries.get(i));
216	                                }
217	                                break;
218	                            }
219	                        } while (++i < entries.size());
220	                        if (replacedEntry == null) {
221	                            newEntries.add(e);
222	                        }
223	                        sortEntries(hostname, newEntries);
224	
225	                        if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
226	                            return scheduleCacheExpirationIfNeeded(ttl, loop);
227	                        }
228	                    } else if (compareAndSet(entries, singletonList(e))) {
229	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
230	                    }
231	                }
232	            } else {
233	                set(singletonList(e));
234	                return scheduleCacheExpirationIfNeeded(ttl, loop);
235	            }
236	        }
237	
238	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
239	            for (;;) {
240	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
241	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
242	                // we can reconsider.
243	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
244	                if (oldFuture == CANCELLED) {
245	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
246	                    // Signal the caller (cache()) to retry with a fresh Entries.
247	                    return false;
248	                }
249	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
250	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
251	                    // It is possible that
252	                    // 1. task will fire in between this line, or
253	                    // 2. multiple timers may be set if there is concurrency
254	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
255	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
256	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
257	                        if (oldFuture != null) {
258	                            oldFuture.cancel(true);
259	                        }
260	                        return true;
261	                    } else {
262	                        // There was something else scheduled in the meantime... Cancel and try again.
263	                        newFuture.cancel(true);
264	                    }
265	                } else {
266	                    return true;
267	                }
268	            }
269	        }
270	
271	        boolean clearAndCancel() {
272	            List<E> entries = getAndSet(Collections.<E>emptyList());
273	            if (entries.isEmpty()) {
274	                return false;
275	            }
276	
277	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
278	            if (expirationFuture != null) {
279	                expirationFuture.cancel(false);
280	            }
281	
282	            return true;
283	        }
284	
285	        @Override
286	        public void run() {
287	            // We always remove all entries for a hostname once one entry expire. This is not the
288	            // most efficient to do but this way we can guarantee that if a DnsResolver
289	            // be configured to prefer one ip family over the other we will not return unexpected
290	            // results to the enduser if one of the A or AAAA records has different TTL settings.
291	            //
292	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
293	            // completely fine to remove the entry even if the TTL is not reached yet.
294	            //
295	            // See https://github.com/netty/netty/issues/7329
296	            // Set CANCELLED before removing from the map so any concurrent scheduleCacheExpirationIfNeeded
297	            // call always sees CANCELLED and returns false (triggering a retry in cache()) rather than
298	            // succeeding its future CAS, returning true, and having the data wiped immediately after.
299	            clearAndCancel();
300	
301	            resolveCache.remove(hostname, this);
302	        }
303	    }
304	}
