205	    /**
206	     * Host / Port tuple used to find a session in the cache.
207	     */
208	    private static final class HostPort {
209	        private final int hash;
210	        private final String host;
211	        private final int port;
212	
213	        HostPort(@Nullable String host, int port) {
214	            this.host = host;
215	            this.port = port;
216	            // Calculate a hashCode that does ignore case. Use -1 for null host to avoid colliding
217	            // with non-null hosts whose AsciiString.hashCode happens to be 0.
218	            this.hash = 31 * (host != null ? AsciiString.hashCode(host) : -1) + port;
219	        }
