221	        @Override
222	        public int hashCode() {
223	            return hash;
224	        }
225	
226	        @Override
227	        public boolean equals(Object obj) {
228	            if (!(obj instanceof HostPort)) {
229	                return false;
230	            }
231	            HostPort other = (HostPort) obj;
232	            return port == other.port &&
233	                    (host == null ? other.host == null : host.equalsIgnoreCase(other.host));
234	        }
