boolean clearAndCancel() {
    // Set CANCELLED before clearing data so any concurrent scheduleCacheExpirationIfNeeded
    // call sees CANCELLED and returns false. If data were cleared first, a concurrent caller
    // could win the future CAS (CANCELLED not yet set), return true to cache(), and then
    // have its data immediately wiped when CANCELLED is set on the next step.
    ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
    List<E> entries = getAndSet(Collections.<E>emptyList());
    if (expirationFuture != null && expirationFuture != CANCELLED) {
        expirationFuture.cancel(false);
    }
    return !entries.isEmpty();
}

